def is_valid(grid, row, col):
    return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

def get_neighbours(grid, row, col):
    for r in range(max(0, row-1), min(len(grid), row+2)):
        for c in range(max(0, col-1), min(len(grid[0]), col+2)):
            if (r, c) != (row, col) and is_valid(grid, r, c):
                yield (r, c)

def solve(grid, start, goal):
    if not is_valid(grid, start[0], start[1]) or not is_valid(grid, goal[0], goal[1]):
        return []
    stack = [(start, [start])]
    seen = set([start])
    while stack:
        node, path = stack.pop()
        if node == goal:
            return path
        for neighbour in get_neighbours(grid, *node):
            if neighbour not in seen:
                seen.add(neighbour)
                new_path = path + [neighbour]
                stack.append((neighbour, new_path))
    return []

