        return []

    queue = deque()
    queue.append(start)
    visited = set([str(start)])

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    while queue:
        cell = queue.popleft()
        if cell == goal:
            path = []
            while cell != start:
                path.insert(0, cell)
                for d in directions:
                    new_cell = (cell[0] + d[0], cell[1] + d[1])
                    if str(new_cell) in visited and new_cell != goal:
                        cell = new_cell
                        break
            path.insert(0, start)
            return path

        for d in directions:
            r, c = cell[0] + d[0], cell[1] + d[1]
            if valid_move(grid, r, c) and str(r, c) not in visited:
                visited.add(str(r, c))
                queue.append((r, c))

    return []

