def solve(grid, start, goal):
    def adjacent Cells(row, col):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = row + dr, col + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                yield nr, nc

    def reconstruct(path):
        stack = [(path[-1], [path[-1]])]
        while stack:
            (cell, path_so_far) = stack.pop()
            if cell == start:
                return path_so_far + [cell]
            for neighbor in adjacentCells(cell[0], cell[1]):
                if neighbor not in path_so_far:
                    stack.append((neighbor, path_so_far + [cell, neighbor]))
        return []

    if start == goal or grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        if start == goal and grid[start[0]][start[1]] == '.':
            return [start]
        return []
    path = [start]
    visited = {start}
    while path:
        current = path[-1]
        if current == goal:
            return reconstruct(path)
        for neighbor in adjacentCells(current[0], current[1]):
            if neighbor not in visited:
                path.append(neighbor)
                visited.add(neighbor)
                break
        else:
            path.pop()
    return []

