from collections import deque

def solve(grid, start, goal):
    def valid_move(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] != '#'

    def get_neighbors(cell):
        return [(cell[0]-1, cell[1]), (cell[0]+1, cell[1]), (cell[0], cell[1]-1), (cell[0], cell[1]+1)]

    def is_valid_path(path):
        return all(grid[row][col] != '#' for row, col in path)

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    queue = deque([(start, [start])])
    visited = set()

    while queue:
        cell, path = queue.popleft()
        if cell == goal and is_valid_path(path):
            return path

        visited.add(cell)

        for neighbor in get_neighbors(cell):
            if valid_move(neighbor[0], neighbor[1]) and neighbor not in visited:
                queue.append((neighbor, path + [neighbor]))

    return []

def print_grid(grid):
    for row in grid:
        print(' '.join(row))

def print_path(path):
    for row in range(len(path)):
        if path[row] == path[0]:
            print('S', end=' ')
        elif path[row] == path[-1]:
            print('G', end=' ')
        else:
            print('.', end=' ')
    print()

def main():
    grid = [
        '.##...#',
        '.#...#.',
        '.##.#.#',
        '.#.##.#',
        '......#',
        '#.....#',
        '#..###.',
        '.##.###',
        '.#.#... ',
        '##.....#',
    ]
    start = (4, 1)
    goal = (8, 5)
    path = solve(grid, start, goal)
    print_path(path)
    if path:
        print('Length of path:', len(path))

if __name__ == '__main__':
    main()

