        if position == goal or is_valid_path_path(path):
            return path
        if position in path: 
            return None
        path.append(position)
        for neighbour in get_neighbours(position):
            result = backtrack(neighbour, path.copy())  
            if result is not None:
                return result
        path.pop() 
        return None

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    return backtrack(start, [])

