    assert 1 <= len(grid) <= 30 and 1 <= len(grid[0]) <= 30, "Grid dimensions out of range"

    row_offsets = (-1, 0, 1, 0)
    col_offsets = (0, -1, 0, 1)

    visited = set()

    def get_neighbors(cell):
        for i, offset in enumerate(row_offsets):
            row = cell[0] + offset
            col = cell[1] + col_offsets[i]
            if 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.' and cell != (row, col):
                yield (row, col)

    def is_valid(cell):
        return 0 <= cell[0] < len(grid) and 0 <= cell[1] < len(grid[0]) and grid[cell[0]][cell[1]] == '.'

    def backtrack(cell, path):
        if cell == goal:
            return [path + [cell]]
        visited.add(cell)
        path = path + [cell]
        neighbors = get_neighbors(cell)
        for neighbor in neighbors:
            if neighbor not in visited:
                result = backtrack(neighbor, path)
                if result:
                    return result
        return []

