    if row - 1 >= 0 and grid[row - 1][col] == '.':
        yield (row - 1, col)
    if row + 1 < len(grid) and grid[row + 1][col] == '.':
        yield (row + 1, col)
    if col - 1 >= 0 and grid[row][col - 1] == '.':
        yield (row, col - 1)
    if col + 1 < len(grid[0]) and grid[row][col + 1] == '.':
        yield (row, col + 1)

