def solve(grid, start, goal):
    def issquare(i, j):
        return 0 <= i < len(grid) and 0 <= j < len(grid[0])

    def isfree(i, j):
        return issquare(i, j) and grid[i][j] == '.'

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def astar(openlist, closedlist, start, goal):
        while openlist:
            path = [(start,) for _ in openlist]
            current = min(openlist, key=lambda x:path[openlist.index(x)].count(x))
            openlist.remove(current)
            if current == goal:
                return path[path.index(goal):]
            closedlist.add(current)
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                next = (current[0] + dx, current[1] + dy)
                if isfree(*next):
                    openlist.add(next)
