from typing import Tuple, List

def solve(grid: List[str], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    def valid(row: int, col: int) -> bool:
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] != '#'

    def neighbors(row: int, col: int) -> List[Tuple[int, int]]:
        return [(row-1, col), (row+1, col), (row, col-1), (row, col+1)]

    def dfs(row: int, col: int, path: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
        if (row, col) == goal:
            return path + [(row, col)]
        path.append((row, col))
        for r, c in neighbors(row, col):
            if valid(r, c) and (r, c) not in path:
                path = dfs(r, c, path)
                if path:
                    return path
        path.pop()
        return []

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    return dfs(*start, []) if valid(*start) else []

