def solve(grid, start, goal):
    if not grid or grid[0] and grid[0][0] == '#':
        return []

    rows, cols = len(grid), len(grid[0])
    open_set = {start}
    came_from, cost_so_far = {}, {start: 0}

    while open_set:
        current = min(open_set, key=lambda pos: cost_so_far.get(pos, float('inf')))

        if current == goal:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            path.reverse()
            return path

        open_set.remove(current)

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_pos = (current[0] + dx, current[1] + dy)
            if (0 <= next_pos[0] < rows) and (0 <= next_pos[1] < cols) and grid[next_pos[0]][next_pos[1]] != '#' and next_pos not in came_from:
                new_cost = cost_so_far[current] + 1
                open_set.add(next_pos)
                cost_so_far[next_pos] = new_cost
                came_from[next_pos] = current

