def find neighbours(grid, row, col):
    """Find the neighbours of a cell in the grid."""
    neighbours = []
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    for dr, dc in directions:
        r, c = row + dr, col + dc
        if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.':
            neighbours.append((r, c))
    return neighbours

def solve(grid, start, goal):
    """Find a path from the start to the goal in the grid."""
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []  # start or goal is a wall
    if start == goal:
        return [start]  # start is the same as the goal

    queue = [(start, [start])]
    visited = set([start])
    while queue:
        (row, col), path = queue.pop(0)
        for r, c in find_neighbours(grid, row, col):
            if (r, c) == goal:
                return path + [(r, c)]
            if (r, c) not in visited:
                queue.append(((r, c), path + [(r, c)]))
                visited.add((r, c))
    return []  # no path exists
