def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    def valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def next_moves(pos):
        for r, c in [(pos[0] - 1, pos[1]), (pos[0] + 1, pos[1]), 
                     (pos[0], pos[1] - 1), (pos[0], pos[1] + 1)]:
            if valid(r, c):
                yield (r, c)

    def dfs(pos, path):
        if pos == goal:
            return [path + [pos]]
        elif len(path) < len(grid[0]) * (rows + 1) / 2:
            for n in next_moves(pos):
                if n not in path:
                    result = dfs(n, path + [pos])
                    if result:
                        return result
        return []

    return dfs(start, []) if start != goal else [start]

