                        path.append((x, y))
                        break
            return path

        visited[x][y] = True
        for dx, dy in directions:
            if 0 <= x + dx < rows and 0 <= y + dy < cols and grid[x + dx][y + dy] == '.' and not visited[x + dx][y + dy]:
                queue.append((x + dx, y + dy))

    return []
