def solve(grid, start, goal):
    def valid_move(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[row]) and grid[row][col] != '#'

    visited = set()
    moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def dfs(row, col, path):
        if (row, col) == goal:
            return [path + [(row, col)]]
        if (row, col) in visited or not valid_move(row, col):
            return None
        visited.add((row, col))
        for move in moves:
            next_row, next_col = row + move[0], col + move[1]
            result = dfs(next_row, next_col, path + [(row, col)])
            if result is not None:
                return result
        visited.remove((row, col))
        return None

    if start == goal and valid_move(start[0], start[1]):
        return [start]
    return dfs(*start, []) or []

